const split = s => String(s || '').split(/\s+/).filter(Boolean);
export const ALIGNMENT = Object.fromEntries(Object.entries(map).map(([key, [perf, content, comp, flag]]) => [key, { perf: split(perf), content: split(content), comp: split(comp), extension: flag === 'ext', review: flag === 'review' }]));
export function alignmentFor(key) { return ALIGNMENT[key] || null; }
